const bal=(g,x,y,w)=>{rect(g,IR,x-3,y,w+6,2.4);for(let q=0;q<=w/4;q++)rect(g,IR,x-2+q*4,y-8,1,8);rect(g,IR,x-3,y-8,w+6,1.2)};
